INSERT INTO feature VALUES('name-coverage','editor','An answer at every name','hover','implemented','uncommon','mainstream editors','Each name the highlighter marks in the corpus answers its definition, is named by the index as a binder, and hovers more than a bare stub, or the coverage ledger holds its kind as owed; a kind the ledger lacks is refused, and a whole sweep refuses a held kind with no gap left.','surface-lsp-core','crates/surface-lsp-core/src/hover/tests/coverage.rs crates/surface-lsp-core/coverage.ledger corpus/model/basics/every-name-answers.gandr','corpus/model/basics/every-name-answers.gandr','#4304');
